package com.gtinwmsqr;
import android.graphics.drawable.Drawable;import android.os.*;import android.print.*;import android.print.pdf.PrintedPdfDocument;import android.graphics.*;import android.graphics.pdf.PdfDocument;
public class QrPrintAdapter extends PrintDocumentAdapter{final android.content.Context c;final Drawable d;PdfDocument doc;QrPrintAdapter(android.content.Context c,Drawable d){this.c=c;this.d=d;}public void onLayout(PrintAttributes o,PrintAttributes n,android.os.CancellationSignal s,LayoutResultCallback cb,Bundle x){if(s.isCanceled()){cb.onLayoutCancelled();return;}cb.onLayoutFinished(new PrintDocumentInfo.Builder("qr.pdf").setContentType(PrintDocumentInfo.CONTENT_TYPE_DOCUMENT).setPageCount(1).build(),true);}public void onWrite(PageRange[] r,android.os.ParcelFileDescriptor f,android.os.CancellationSignal s,WriteResultCallback cb){doc=new PrintedPdfDocument(c,new PrintAttributes.Builder().setMediaSize(PrintAttributes.MediaSize.ISO_A4).build());PdfDocument.Page p=doc.startPage(1);Canvas can=p.getCanvas();int w=can.getWidth(),h=can.getHeight();int size=Math.min(w,h)*2/3;int l=(w-size)/2,t=(h-size)/2;d.setBounds(l,t,l+size,t+size);d.draw(can);doc.finishPage(p);try{doc.writeTo(new java.io.FileOutputStream(f.getFileDescriptor()));cb.onWriteFinished(new PageRange[]{PageRange.ALL_PAGES});}catch(Exception e){cb.onWriteFailed(e.toString());}finally{doc.close();}}
}
